CHECKS = ["check_shared", "check_setup", "check_forward_eval", "check_forward_sample", "check_merge"]


def _t(flat, shape, dtype=torch.float64):
    return torch.tensor(flat, dtype=dtype).reshape(shape)


def _t32(flat, shape):
    return torch.tensor(flat, dtype=torch.float32).reshape(shape)


def check_shared(solve):
    f = EXPECTED["F1"]
    A, B, A32, B32 = solve(mode="shared_projections", r=f["r"], in_max=f["in_max"],
                           out_max=f["out_max"], prng_key=f["key"])
    assert A.dtype == torch.float64 and A32.dtype == torch.float32
    assert torch.allclose(A32, _t32(f["A32"], (f["r"] * 2, f["in_max"])), atol=0, rtol=0)
    assert torch.allclose(B32, _t32(f["B32"], (f["out_max"], f["r"])), atol=0, rtol=0)
    assert torch.allclose(A, _t(f["A_shared"], (f["r"] * 2, f["in_max"])), atol=1e-12, rtol=0)
    assert torch.allclose(B, _t(f["B_shared"], (f["out_max"], f["r"])), atol=1e-12, rtol=0)
    # slice account
    A1, B1 = solve(mode="slice_pair", a_shared=A, b_shared=B,
                   in_features=f["in1"], out_features=f["out1"])
    assert torch.allclose(A1, _t(f["A1"], (f["r"] * 2, f["in1"])), atol=1e-12, rtol=0)
    assert torch.allclose(B1, _t(f["B1"], (f["out1"], f["r"])), atol=1e-12, rtol=0)
    # A rows sliced by columns only (2r kept), B rows sliced from front
    assert A1.shape == (f["r"] * 2, f["in1"]) and B1.shape == (f["out1"], f["r"])


def check_setup(solve):
    su = EXPECTED["setup"]
    # official init_weights=True: lambda_d = d_initial (2r,), lambda_b = 0 (ones creation cleared by reset)
    out = solve(mode="layer_setup", r=4, out_features=6, d_initial=su["d_initial"])
    assert torch.allclose(out["lambda_d"], torch.tensor(su["lambda_d_full"], dtype=torch.float64))
    assert torch.allclose(out["lambda_b"], torch.tensor(su["lambda_b_full"], dtype=torch.float64))
    assert torch.allclose(out["lambda_b"], torch.zeros(6, dtype=torch.float64))
    out2 = solve(mode="layer_setup", r=1, out_features=7, d_initial=su["d_initial2"])
    assert torch.allclose(out2["lambda_d"], torch.tensor(su["lambda_d2_full"], dtype=torch.float64))
    assert torch.allclose(out2["lambda_b"], torch.zeros(7, dtype=torch.float64))
    # init_weights=False branch: lambda_b stays ones (lambda_d keeps randn — unanchorable)
    assert torch.allclose(out["lambda_b_uninit"], torch.tensor(su["lambda_b_uninit"], dtype=torch.float64))
    assert torch.allclose(out2["lambda_b_uninit"], torch.ones(7, dtype=torch.float64))
    # default d_initial
    out3 = solve(mode="layer_setup", r=2, out_features=3)
    assert torch.allclose(out3["lambda_d"], torch.full((4,), 0.1, dtype=torch.float64))
    assert torch.allclose(out3["lambda_b"], torch.zeros(3, dtype=torch.float64))


def check_forward_eval(solve):
    f = EXPECTED["F1"]
    r = f["r"]
    ld = _t(f["lambda_d"], (2 * r,))
    lb = _t(f["lambda_b"], (f["out1"],))
    A1 = _t(f["A1"], (2 * r, f["in1"]))
    B1 = _t(f["B1"], (f["out1"], r))
    x = _t(f["x1"], (2, 5, f["in1"]))
    got = solve(mode="forward_delta", x=x, lambda_d=ld, lambda_b=lb, a_s=A1, b_s=B1)
    want = _t(f["delta1"], (2, 5, f["out1"]))
    assert torch.allclose(got, want, atol=1e-10), float((got - want).abs().max())
    # eval path z == mu: no eps -> deterministic
    got2 = solve(mode="forward_delta", x=x, lambda_d=ld, lambda_b=lb, a_s=A1, b_s=B1)
    assert torch.allclose(got, got2, atol=0)
    # merge identity: delta(x) == x @ dW.T (no base offset involved)
    dW = solve(mode="merge_delta", lambda_d=ld, lambda_b=lb, a_s=A1, b_s=B1)
    assert torch.allclose(got, x @ dW.T, atol=1e-10)


def check_forward_sample(solve):
    f = EXPECTED["F1"]
    r = f["r"]
    ld = _t(f["lambda_d"], (2 * r,))
    lb = _t(f["lambda_b"], (f["out1"],))
    A1 = _t(f["A1"], (2 * r, f["in1"]))
    B1 = _t(f["B1"], (f["out1"], r))
    x = _t(f["x1"], (2, 5, f["in1"]))
    eps = _t(f["eps"], (2, 5, r))
    got = solve(mode="forward_delta", x=x, lambda_d=ld, lambda_b=lb, a_s=A1, b_s=B1, eps=eps)
    want = _t(f["delta1_s"], (2, 5, f["out1"]))
    assert torch.allclose(got, want, atol=1e-10), float((got - want).abs().max())
    # manual reparam: mu + eps*exp(0.5*logvar)
    pre = ld * (x @ A1.T)
    mu, logvar = pre.chunk(2, dim=-1)
    z = mu + eps * torch.exp(0.5 * logvar)
    assert torch.allclose(got, lb * (z @ B1.T), atol=1e-10)
    # sampled != eval (observable branch difference)
    ev = solve(mode="forward_delta", x=x, lambda_d=ld, lambda_b=lb, a_s=A1, b_s=B1)
    assert not torch.allclose(got, ev)
    # F2 r=1 sampling
    f2 = EXPECTED["F2"]
    ld2 = _t(f2["lambda_d2"], (2 * f2["r"],))
    lb2 = _t(f2["lambda_b2"], (f2["out2"],))
    A2 = _t(f2["A2s"], (2 * f2["r"], f2["in2"]))
    B2 = _t(f2["B2s"], (f2["out2"], f2["r"]))
    x2 = _t(f2["x2"], (4, f2["in2"]))
    eps2 = _t(f2["eps2"], (4, f2["r"]))
    got2 = solve(mode="forward_delta", x=x2, lambda_d=ld2, lambda_b=lb2, a_s=A2, b_s=B2, eps=eps2)
    want2 = _t(f2["delta2_s"], (4, f2["out2"]))
    assert torch.allclose(got2, want2, atol=1e-10)


def check_merge(solve):
    f = EXPECTED["F1"]
    r = f["r"]
    ld = _t(f["lambda_d"], (2 * r,))
    lb = _t(f["lambda_b"], (f["out1"],))
    A1 = _t(f["A1"], (2 * r, f["in1"]))
    B1 = _t(f["B1"], (f["out1"], r))
    dW = solve(mode="merge_delta", lambda_d=ld, lambda_b=lb, a_s=A1, b_s=B1)
    want = _t(f["dW1"], (f["out1"], f["in1"]))
    assert torch.allclose(dW, want, atol=1e-10), float((dW - want).abs().max())
    # mu half only: mutating the logvar half must not change dW
    ld2 = ld.clone()
    ld2[r:] = ld2[r:] * 7.3
    dW2 = solve(mode="merge_delta", lambda_d=ld2, lambda_b=lb, a_s=A1, b_s=B1)
    assert torch.allclose(dW2, dW, atol=1e-12)
    # but forward eval DOES change (logvar half is ignored only in eval; still mu unchanged)
    # eval ignores logvar entirely: forward eval with ld2 == forward eval with ld
    x = _t(f["x1"], (2, 5, f["in1"]))
    ev1 = solve(mode="forward_delta", x=x, lambda_d=ld, lambda_b=lb, a_s=A1, b_s=B1)
    ev2 = solve(mode="forward_delta", x=x, lambda_d=ld2, lambda_b=lb, a_s=A1, b_s=B1)
    assert torch.allclose(ev1, ev2, atol=1e-12)
    # zero mu-half -> zero dW (zero-start semantics)
    f3 = EXPECTED["F3"]
    ldz = torch.cat([torch.zeros(r), torch.ones(r)])
    dz = solve(mode="merge_delta", lambda_d=ldz, lambda_b=lb, a_s=A1, b_s=B1)
    assert torch.allclose(dz, torch.zeros(f["out1"], f["in1"], dtype=torch.float64), atol=1e-12)
    # F3 uniform lambda account
    ld0 = _t(f3["lambda_d0"], (2 * r,))
    dW0 = solve(mode="merge_delta", lambda_d=ld0, lambda_b=lb, a_s=A1, b_s=B1)
    assert torch.allclose(dW0, _t(f3["dW0"], (f["out1"], f["in1"])), atol=1e-10)
    d0 = solve(mode="forward_delta", x=x, lambda_d=ld0, lambda_b=lb, a_s=A1, b_s=B1)
    assert torch.allclose(d0, _t(f3["delta0"], (2, 5, f["out1"])), atol=1e-10)
    assert torch.allclose(d0, x @ dW0.T, atol=1e-10)
    # F2 merge identity
    f2 = EXPECTED["F2"]
    ld2m = _t(f2["lambda_d2"], (2 * f2["r"],))
    lb2 = _t(f2["lambda_b2"], (f2["out2"],))
    A2 = _t(f2["A2s"], (2 * f2["r"], f2["in2"]))
    B2 = _t(f2["B2s"], (f2["out2"], f2["r"]))
    x2 = _t(f2["x2"], (4, f2["in2"]))
    dW2 = solve(mode="merge_delta", lambda_d=ld2m, lambda_b=lb2, a_s=A2, b_s=B2)
    delta2 = solve(mode="forward_delta", x=x2, lambda_d=ld2m, lambda_b=lb2, a_s=A2, b_s=B2)
    assert torch.allclose(delta2, x2 @ dW2.T, atol=1e-10)
    assert torch.allclose(dW2, _t(f2["dW2"], (f2["out2"], f2["in2"])), atol=1e-10)


def solve(mode=None, **kw):
    import solution
    return solution.solve(mode=mode, **kw)
